// Multiple classes in one file for the runnable demo.
package com.bank.advisor;

import java.util.logging.*;

public class BrokerChoiceDemo {

    private static final Logger log = Logger.getLogger(BrokerChoiceDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BrokerAdvisor advisor = new BrokerAdvisor();

        // Requirement 1: compliance seven-year replay / event sourcing.
        Requirement compliance = new Requirement("7yr trade replay / event sourcing");
        compliance.needsLongReplay = true;
        compliance.needsStreamProcessing = true;
        compliance.needsFlexibleRouting = false;
        compliance.routingChangesOften = false;
        Recommendation r1 = advisor.recommend(compliance);
        log.info(() -> r1.toString());

        // Requirement 2: many desks, changing routing needs, no topic creation.
        Requirement desks = new Requirement("Trading desks, diverse changing slices");
        desks.needsLongReplay = false;
        desks.needsStreamProcessing = false;
        desks.needsFlexibleRouting = true;
        desks.routingChangesOften = true;
        Recommendation r2 = advisor.recommend(desks);
        log.info(() -> r2.toString());

        // Concrete illustration of each strength.
        log.info("KAFKA replay example: reset trade.events group to earliest and recompute ledger");
        log.fine("  kafka-consumer-groups.sh --reset-offsets --to-earliest --execute");
        log.info("SOLACE dynamic routing example: Rajesh's desk changes subscription live");
        log.fine("  subscribe txn/IN/large  ->  (later) subscribe txn/IN/>");
    }
}

