class Requirement {
    final String name;
    boolean needsLongReplay;        // keep history, rewind, event sourcing
    boolean needsStreamProcessing;  // Kafka Streams / ksqlDB
    boolean needsFlexibleRouting;   // broker-native hierarchical wildcards
    boolean routingChangesOften;    // consumers change interest frequently
    Requirement(String name) { this.name = name; }
}

// ─── Would be in model/Recommendation.java ───
class Recommendation {
    final String requirement;
    final String choice;
    final String reason;
    Recommendation(String requirement, String choice, String reason) {
        this.requirement = requirement; this.choice = choice; this.reason = reason;
    }
    @Override public String toString() {
        return "REQ[" + requirement + "] -> CHOOSE " + choice + " BECAUSE " + reason;
    }
}

// ─── Would be in service/BrokerAdvisor.java ───
class BrokerAdvisor {
    private static final Logger log = Logger.getLogger(BrokerAdvisor.class.getName());

    Recommendation recommend(Requirement req) {
        // Kafka wins when durability/replay/stream-processing dominate.
        if (req.needsLongReplay || req.needsStreamProcessing) {
            log.fine(() -> "scoring " + req.name + ": durability/replay dominant");
            return new Recommendation(req.name, "KAFKA",
                "durable partitioned log gives long-term retention, deterministic replay, "
                + "event sourcing, and the Kafka Streams/ksqlDB ecosystem with per-key ordering");
        }
        // Solace wins when flexible, changing, broker-side routing dominates.
        if (req.needsFlexibleRouting || req.routingChangesOften) {
            log.fine(() -> "scoring " + req.name + ": flexible routing dominant");
            return new Recommendation(req.name, "SOLACE",
                "broker-native hierarchical wildcard subscriptions let diverse, changing "
                + "consumers filter dynamically with no new topics (no topic proliferation)");
        }
        // Neither dominant: default to Kafka as the durable backbone.
        return new Recommendation(req.name, "KAFKA",
            "no dominant routing need; prefer the durable event backbone as default");
    }
}

